bfs-bidirectional:
front = {start: 0}; back = {end: 0}
while front and back:
    # Always expand the SMALLER frontier:
    if len(front) > len(back): front, back = back, front
    nxt = {}
    for u, d in front.items():
        for v in neighbors(u):
            if v in back: return d + back[v] + 1
            if v not in nxt and v not in front: nxt[v] = d + 1
    front = nxt
return -1

