bfs-level-connect:
# O(1) space — use already-built next pointers from prev level:
leftmost = root
while leftmost:
    cur = leftmost; prev = None; head_next = None
    while cur:
        for child in (cur.left, cur.right):
            if child:
                if prev: prev.next = child
                else:    head_next = child
                prev = child
        cur = cur.next
    leftmost = head_next

