# Sum of subarray minimums:
prev_less = [-1] * n; stack = []
for i in range(n):
    while stack and a[stack[-1]] >= a[i]: stack.pop()
    prev_less[i] = stack[-1] if stack else -1
    stack.append(i)
stack.clear()
next_less = [n]  * n
for i in range(n - 1, -1, -1):
    while stack and a[stack[-1]] > a[i]: stack.pop()
    next_less[i] = stack[-1] if stack else n
    stack.append(i)
ans = sum(a[i] * (i - prev_less[i]) * (next_less[i] - i) for i in range(n))

